ee:variables.ee:set-variable:
%dw 2.0
output application/xml
import * from dw::core::Strings
---
subscribers @('xmlns:xsi':"http://www.w3.org/2001/XMLSchema-instance", 'xsi:noNamespaceSchemaLocation':"xsd/ModificarDatosCuentaInput.xsd"):{
	subscriber_particulars:{
		subscriber_data @(action:"modify"):{
			user: payload.user,
			subscriber_id: payload.Customer.SubscriberId,
			first_name: payload.Customer.FirstName,
			last_name: payload.Customer.LastName,
			subscriber_name: payload.Customer.SuscriberName
		},
		billing_address_data @(action:"modify"): {
			bill_address1: payload.Address.Address,
			bill_city: rightPad(payload.Address.CityCode, 8, "0"),
			bill_country_code: payload.Address.CountryCode,
			bill_state_code: leftPad(payload.Address.StateCode, 2, "0"),
			bill_billing_name: payload.Customer.BillBillingName
		},
		address_data @(action:"modify"): {
			address1: payload.Address.Address,
			address_geo_code: rightPad(payload.Address.CityCode, 8, "0"),
			city: payload.Address.City,
			country_code: payload.Address.CountryCode,
			state_code: leftPad(payload.Address.StateCode, 2, "0")
		},
		(email_data @(action:"add"): {
			email_address: payload.Customer.Email default "",
			email_is_primary_flag: if (payload.InvoiceMethod.DeliveryType == "Email") "Y" else "N"
		}) if (!isBlank(payload.Customer.Email)),
		invoice_method_data @(action:"modify"):{
			invoice_method_name: payload.InvoiceMethod.MethodName,
			invoice_delivery_name: payload.InvoiceMethod.DeliveryType,
			invoice_delivery_mobile: payload.InvoiceMethod.MobilePhone	
		}
	}
}
